head.script:
scwin.__isCheckLog = function() {
	var log = WebSquare.logger.getLog();
	return log.indexOf("A duplicate widget id was used") >= 0 || log.indexOf("A widget cannot be added to that location") >= 0 || log.indexOf("중복된 widget id를 사용했습니다") >= 0 || log.indexOf("해당 위치에 widget을 추가할 수 없습니다") >= 0;
};

scwin.onpageload2 = function() {
	if (!window['edu']) {
		window["edu"] = {};
	}
	edu.trigger1_onclick = function(e) {
		widgetContainer1.addWidgets({
			id: "widgetContainer_WPF1733_WSQ2857widget01",
			title: "위젯01",
			src: "/sample/common_link/widgetContainer_widget01_WPF-1733_(WSQ-2857)_content.xml",
			scope: true,
			unitWidth: 1,
			unitHeight: 1
		});
	};
	window.count1 = 0;
	edu.trigger2_onclick = function(e) {
		count1++;
		widgetContainer2.addWidgets({
			id: "widgetContainer_WPF1733_WSQ2857widget" + count1,
			title: "위젯" + count1,
			src: "/sample/common_link/widgetContainer_widget01_WPF-1733_(WSQ-2857)_content.xml",
			scope: true,
			unitWidth: 1,
			unitHeight: 1
		});
	};
};
